package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import org.apache.commons.cli.CommandLine;
import org.apache.commons.cli.Option;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CommandLine_hasOption_TriageGen0Test {

    private Option optionA;
    private Option optionB;

    @Before
    public void setUp() {
        optionA = Option.builder("a").longOpt("alpha").desc("description a").build();
        optionB = Option.builder("b").longOpt("beta").desc("description b").build();
    }

    /**
     * This test simulates the internal state of CommandLine by using a Parser 
     * or manual construction if possible. Since CommandLine is usually 
     * created by DefaultParser, we use a parser to ensure the internal 
     * 'options' map is correctly populated for the test.
     */
    @Test
    public void testHasOption_WithExistingShortOption() throws Exception {
        String argString = "-a";
        Options options = new Options();
        options.addOption(optionA);
        options.addOption(optionB);

        CommandLineParser parser = new DefaultParser();
        CommandLine cmd = parser.parse(options, argString.split(" "));

        assertTrue("Should return true for existing short option 'a'", cmd.hasOption("a"));
    }

    @Test
    public void testHasOption_WithExistingLongOption() throws Exception {
        String argString = "--alpha";
        Options options = new Options();
        options.addOption(optionA);
        options.addOption(optionB);

        CommandLineParser parser = new DefaultParser();
        CommandLine cmd = parser.parse(options, argString.split(" "));

        assertTrue("Should return true for existing long option 'alpha'", cmd.hasOption("alpha"));
    }

    @Test
    public void testHasOption_WithNonExistentOption() throws Exception {
        String argString = "-a";
        Options options = new Options();
        options.addOption(optionA);
        options.addOption(optionB);

        CommandLineParser parser = new DefaultParser();
        CommandLine cmd = parser.parse(options, argString.split(" "));

        assertFalse("Should return false for option that was not provided", cmd.hasOption("b"));
        assertFalse("Should return false for option that does not exist in definition", cmd.hasOption("c"));
    }

    @Test
    public void testHasOption_WithNullInput() throws Exception {
        // Depending on implementation, containsKey(null) might throw NPE or return false.
        // Most Map implementations used in Commons CLI will throw NPE if key is null.
        Options options = new Options();
        options.addOption(optionA);
        CommandLineParser parser = new DefaultParser();
        CommandLine cmd = parser.parse(options, new String[]{});

        try {
            cmd.hasOption(null);
        } catch (NullPointerException e) {
            // If the internal map is a HashMap, it might handle null, 
            // but if it's a TreeMap or similar, it throws NPE.
            // This test ensures we observe the actual behavior.
        }
    }

    @Test
    public void testHasOption_EmptyCommandLine() throws Exception {
        Options options = new Options();
        options.addOption(optionA);
        CommandLineParser parser = new DefaultParser();
        CommandLine cmd = parser.parse(options, new String[]{});

        assertFalse("Should return false when no options are provided", cmd.hasOption("a"));
    }
}
